(()=>{const canvas=new OffscreenCanvas(2,2),gl=canvas.getContext('webgl2',{antialias:false}),b=gl.createBuffer();const result={created:gl.isBuffer(b)};gl.bindBuffer(gl.ARRAY_BUFFER,b);result.bound=gl.isBuffer(b);gl.bufferData(gl.ARRAY_BUFFER,new Uint8Array([1,2,3,4]),gl.STATIC_DRAW);gl.bufferSubData(gl.ARRAY_BUFFER,1,new Uint8Array([8,9]));const bytes=new Uint8Array(4);gl.getBufferSubData(gl.ARRAY_BUFFER,0,bytes);result.bytes=Array.from(bytes);result.size=gl.getBufferParameter(gl.ARRAY_BUFFER,gl.BUFFER_SIZE);gl.clearColor(1,0,0,1);gl.clear(gl.COLOR_BUFFER_BIT);const pixels=new Uint8Array(16);gl.readPixels(0,0,2,2,gl.RGBA,gl.UNSIGNED_BYTE,pixels);result.pixels=Array.from(pixels);canvas.width=2;result.clearAfterResize=Array.from(gl.getParameter(gl.COLOR_CLEAR_VALUE));result.viewport=Array.from(gl.getParameter(gl.VIEWPORT));gl.readPixels(0,0,2,2,gl.RGBA,gl.UNSIGNED_BYTE,pixels);result.resizePixels=Array.from(pixels);result.bufferSurvives=gl.getBufferParameter(gl.ARRAY_BUFFER,gl.BUFFER_SIZE);gl.deleteBuffer(b);result.deleted=gl.isBuffer(b);result.binding=gl.getParameter(gl.ARRAY_BUFFER_BINDING);return result})()
